// Insert inserts the record into the database
func (t *CurrencyExchangeRate) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyExchangeRateTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Currency_code,
		t.Starting_date,
		t.Exchange_rate_amount,
		t.Adjustment_exch_rate_amount,
		t.Relational_currency_code,
		t.Relational_exch_rate_amount,
		t.Fix_exchange_rate_amount,
		t.Relational_adjmt_exch_rate_amt,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (currency_code, starting_date, exchange_rate_amount, adjustment_exch_rate_amount, relational_currency_code, relational_exch_rate_amount, fix_exchange_rate_amount, relational_adjmt_exch_rate_amt) VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (currency_code, starting_date) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Currency_Exchange_Rate: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(CurrencyExchangeRateTableName, key)
		return false
	}
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *CurrencyExchangeRate) InsertAll(records []*CurrencyExchangeRate, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Currency_code,
			r.Starting_date,
			r.Exchange_rate_amount,
			r.Adjustment_exch_rate_amount,
			r.Relational_currency_code,
			r.Relational_exch_rate_amount,
			r.Fix_exchange_rate_amount,
			r.Relational_adjmt_exch_rate_amt,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyExchangeRateTableName)
	columns := []string{"currency_code", "starting_date", "exchange_rate_amount", "adjustment_exch_rate_amount", "relational_currency_code", "relational_exch_rate_amount", "fix_exchange_rate_amount", "relational_adjmt_exch_rate_amt"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *CurrencyExchangeRate) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("currency_code") {
			keyChanged = true
		}
		if t.hasFieldChanged("starting_date") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyExchangeRateTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("currency_code") {
			setClauses = append(setClauses, "currency_code = ?")
			values = append(values, t.Currency_code)
		}
		if t.hasFieldChanged("starting_date") {
			setClauses = append(setClauses, "starting_date = ?")
			values = append(values, t.Starting_date)
		}
		if t.hasFieldChanged("exchange_rate_amount") {
			setClauses = append(setClauses, "exchange_rate_amount = ?")
			values = append(values, t.Exchange_rate_amount)
		}
		if t.hasFieldChanged("adjustment_exch_rate_amount") {
			setClauses = append(setClauses, "adjustment_exch_rate_amount = ?")
			values = append(values, t.Adjustment_exch_rate_amount)
		}
		if t.hasFieldChanged("relational_currency_code") {
			setClauses = append(setClauses, "relational_currency_code = ?")
			values = append(values, t.Relational_currency_code)
		}
		if t.hasFieldChanged("relational_exch_rate_amount") {
			setClauses = append(setClauses, "relational_exch_rate_amount = ?")
			values = append(values, t.Relational_exch_rate_amount)
		}
		if t.hasFieldChanged("fix_exchange_rate_amount") {
			setClauses = append(setClauses, "fix_exchange_rate_amount = ?")
			values = append(values, t.Fix_exchange_rate_amount)
		}
		if t.hasFieldChanged("relational_adjmt_exch_rate_amt") {
			setClauses = append(setClauses, "relational_adjmt_exch_rate_amt = ?")
			values = append(values, t.Relational_adjmt_exch_rate_amt)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "exchange_rate_amount = ?")
		values = append(values, t.Exchange_rate_amount)
		setClauses = append(setClauses, "adjustment_exch_rate_amount = ?")
		values = append(values, t.Adjustment_exch_rate_amount)
		setClauses = append(setClauses, "relational_currency_code = ?")
		values = append(values, t.Relational_currency_code)
		setClauses = append(setClauses, "relational_exch_rate_amount = ?")
		values = append(values, t.Relational_exch_rate_amount)
		setClauses = append(setClauses, "fix_exchange_rate_amount = ?")
		values = append(values, t.Fix_exchange_rate_amount)
		setClauses = append(setClauses, "relational_adjmt_exch_rate_amt = ?")
		values = append(values, t.Relational_adjmt_exch_rate_amt)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["currency_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Currency_code)
	}
	if old, ok := t.oldValues["starting_date"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Starting_date)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND currency_code = ? AND starting_date = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Currency_Exchange_Rate: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *CurrencyExchangeRate) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "currency_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Currency_code.Equal(old)
		}
	case "starting_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Starting_date.Equal(old)
		}
	case "exchange_rate_amount":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Exchange_rate_amount.Equal(old)
		}
	case "adjustment_exch_rate_amount":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Adjustment_exch_rate_amount.Equal(old)
		}
	case "relational_currency_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Relational_currency_code.Equal(old)
		}
	case "relational_exch_rate_amount":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Relational_exch_rate_amount.Equal(old)
		}
	case "fix_exchange_rate_amount":
		if old, ok := oldValue.(CurrencyExchangeRateFix_exchange_rate_amount); ok {
			return t.Fix_exchange_rate_amount != old
		}
	case "relational_adjmt_exch_rate_amt":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Relational_adjmt_exch_rate_amt.Equal(old)
		}
	}

	return false
}

