// ModifyAll updates a field for all records matching current filters
// Returns the number of records modified
func (t *CurrencyExchangeRate) ModifyAll(fieldName string, newValue interface{}) int {
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyExchangeRateTableName)
	column, ok := t.columnName(fieldName)
	if !ok {
		fmt.Printf("Error: ModifyAll on unknown field %q of Currency_Exchange_Rate\n", fieldName)
		return 0
	}
	where, args := t.buildWhereClause()

	// Build UPDATE SQL
	updateSQL := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s`, tableName, column, where)

	// Prepend newValue to args
	allArgs := append([]interface{}{newValue}, args...)

	// Convert placeholders for PostgreSQL
	updateSQL = t.convertPlaceholders(updateSQL, len(allArgs))

	result, err := t.exec().Exec(updateSQL, allArgs...)
	if err != nil {
		fmt.Printf("Error: Failed to modify all Currency_Exchange_Rate: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

